var n = (flow.get('candump_restarts') || 0) + 1;
flow.set('candump_restarts', n);

var rc = (typeof msg.payload === 'object') ? JSON.stringify(msg.payload) : msg.payload;
node.warn('czone candump exited (rc ' + rc + ') — restart #' + n + ' in 5s');
node.status({ fill: 'red', shape: 'ring', text: 'candump exited — restart #' + n });
return msg;

// exec stdout arrives in chunks, not lines: reassemble and decode every line
var chunk = msg.payload;
if (Buffer.isBuffer(chunk)) chunk = chunk.toString('utf8');
if (typeof chunk !== 'string') return null;

chunk = (context.get('partial') || '') + chunk;
var lines = chunk.split('\n');
context.set('partial', lines.pop());

var msgs = [];
for (var n = 0; n < lines.length; n++) {
    var match = lines[n].match(/\scan\d+\s+([0-9A-Fa-f]+)\s+\[(\d+)\]\s+([0-9A-Fa-f\s]+)/);
    if (!match) continue;

    var canid = parseInt(match[1], 16); // full 29-bit ID
    var hexBytes = match[3].trim().split(/\s+/);
    msgs.push({
        payload: {
            canid: canid,
            src: canid & 0xFF,
            dlc: parseInt(match[2], 10),
            data: Buffer.from(hexBytes.map(function (h) { return parseInt(h, 16); }))
        }
    });
}

return [msgs];

// PGN 127501 (Binary Switch Bank Status) decoder.
// Trust ONLY bank instance 1 (the CZone Output Interface): the Navico autopilot
// (src 0x0C) broadcasts 127501 instance 0 "all OFF" at 5 Hz — ingesting those
// flips the tracked state several times a second and strobes the lights.
var f = msg.payload;
if (!f || !f.data || f.data.length < 4) return null;
if (((f.canid >> 8) & 0x3FFFF) !== 0x1F20D) return null; // 127501 only
var d = f.data;
if (d[0] !== 0x01) return null; // bank instance 1 only

var now = Date.now();
var states = flow.get('czState') || {};
var echo = flow.get('czEcho') || {};
var names = {1:'Bilge1',2:'Bilge2',3:'Horn',4:'Helm',5:'Nav',6:'Anchor',7:'Red',8:'Fly',9:'Underwater',10:'Bow1',11:'Bow2'};
var outputs = [null,null,null,null,null,null,null,null,null,null,null];
var changed = [];

for (var sw = 1; sw <= 11; sw++) {
    var v = (d[Math.floor((sw-1)/4)+1] >> (((sw-1)%4)*2)) & 0x03;
    if (v > 1) continue; // 2/3 = error/unavailable
    var prev = states[sw];
    states[sw] = {state: v, ts: now};
    if (prev && prev.state === v) continue;
    // Push to the virtual switch only on change: idempotent D-Bus writes
    // saturate the bus and starve user clicks.
    var m = {payload: {}, _czoneSync: true};
    m.payload['/SwitchableOutput/output_1/State'] = v;
    outputs[sw-1] = m;
    // Remember the value we are pushing, per switch AND per value. The switch
    // node strips _czoneSync, so this write returns as a command a moment later
    // and the control engine needs to recognise and drop it.
    if (!echo[sw]) echo[sw] = {};
    echo[sw][v] = now;
    changed.push(names[sw] + (v ? ' ON' : ' OFF'));
}
flow.set('czState', states);
flow.set('czEcho', echo);

if (!changed.length) return null;
node.status({fill: 'green', shape: 'dot',
    text: changed.join(', ') + ' @' + new Date().toLocaleTimeString()});
return outputs;

var states = flow.get('czState') || {};
var pending = flow.get('czPending') || {};
var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Helm Lights',5:'Nav Lights',6:'Anchor Light',7:'Red Light',8:'Flybridge Lights',9:'Underwater Light',10:'Bow Light 1',11:'Bow Light 2'};
var now = Date.now();
var lines = [];
for (var i = 1; i <= 11; i++) {
    var s = states[i];
    var st = s ? ((s.state === 1 ? 'ON ' : 'OFF') + ' ' + Math.round((now - s.ts)/1000) + 's ago') : '???';
    var flag = pending[i] ? ' [pending ' + (pending[i].target ? 'ON' : 'OFF') + ', ' + pending[i].sends + ' press]' : '';
    lines.push('Sw' + (i<10?' ':'') + i + ' ' + st + '  ' + names[i] + flag);
}
msg.payload = lines.join('\n');
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:1, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:2, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:3, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:4, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:5, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:6, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:7, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:8, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:9, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:10, action: msg.payload ? 'on' : 'off'};
return msg;

if (msg._czoneSync) return null;
msg.payload = {switch:11, action: msg.payload ? 'on' : 'off'};
return msg;

// CZone Control Engine v7.1
// Input: { switch: 1-11, action: 'on'|'off'|'toggle' }
//
// Drives PGN 127502 **bank instance 1**, the same channel the Simrad MFD uses.
// Only bank instance 1 is used. A CZone configuration may define further
// banks over the same physical outputs with different switch types, but the
// output is the OR of the banks: a secondary bank can force an output on, yet
// its OFF cannot clear a latch set on bank 1 by a keypad or the MFD. Bank 1 is
// the user latch everything else shares, so everything below speaks bank 1.

// CZone circuit semantics. How a PGN 127502 bank-1 bit is interpreted is
// decided by the CIRCUIT's own CZone configuration, not by who sent the frame —
// the MFD, the keypads and Node-RED get identical treatment:
//
//   LATCHING (4-11, the lights): 01 is a button press and TOGGLES the latch;
//     00 is the release and is ignored.
//   MOMENTARY (1-3, bilge pumps + horn): the output FOLLOWS the button —
//     01 = on, 00 = off, level control, no toggling.
//
// A latching-style press+release sent to a momentary circuit switches it on and
// then straight back off, so the two must not be conflated.
var MOMENTARY = {1: true, 2: true, 3: true};

var now = Date.now();

// Deploy-echo guard: on (re)deploy every virtual switch emits its initial OFF
// out the command side before any 127501 has been decoded. Drop everything for
// 12s — by then candump is running and real state is synced into the switches.
var deployTs = flow.get('deployTs') || 0;
if (now - deployTs < 12000) {
    node.status({fill:'grey', shape:'ring', text:'deploy guard (' + Math.ceil((12000 - (now - deployTs))/1000) + 's left)'});
    return null;
}

var cmd = msg.payload;
if (!cmd || !cmd.switch || !cmd.action) {
    node.warn('Need {switch: 1-11, action: on|off|toggle}');
    return null;
}

var sw = parseInt(cmd.switch);
var action = String(cmd.action).toLowerCase();
if (!(sw >= 1 && sw <= 11)) { node.warn('Switch must be 1-11'); return null; }

var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Helm Lights',5:'Nav Lights',6:'Anchor Light',7:'Red Light',8:'Flybridge Lights',9:'Underwater Light',10:'Bow Light 1',11:'Bow Light 2'};

function frame(sw, bit) {
    // PGN 127502 bank instance 1, 2 bits per switch: 01 = pressed/on,
    // 00 = released/off, 11 = leave alone. CAN ID 0DF20EFE mirrors the MFD's own
    // frames (0DF20E17, priority 3) with our unclaimed source address.
    var data = [0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF];
    var byteIdx = Math.floor((sw - 1) / 4) + 1;
    var bitPos = ((sw - 1) % 4) * 2;
    data[byteIdx] = (data[byteIdx] & (~(0x03 << bitPos) & 0xFF)) | (bit << bitPos);
    return 'cansend can0 0DF20EFE#' + data.map(function(b) {
        return ('0' + b.toString(16).toUpperCase()).slice(-2); }).join('');
}

var states = flow.get('czState') || {};
var st = states[sw];

// The CZone output interface broadcasts 127501 every 2s, so anything older than
// 6s means the capture has stopped. A latching press is a toggle, so without
// trustworthy state we cannot know which way it would go — refuse, don't guess.
if (!st || now - st.ts > 6000) {
    var age = st ? Math.round((now - st.ts) / 1000) + 's old' : 'never seen';
    // The re-request below is a formality: the UC1 NAKs every ISO Request.
    // State recovers anyway — it broadcasts every 2s — so stale state here
    // means the capture process itself has died.
    node.warn('CZone: ' + names[sw] + ' command refused — 127501 state ' + age + '. Capture may be dead.');
    node.status({fill:'red', shape:'ring', text:names[sw] + ' refused: stale state'});
    return [{payload:'cansend can0 18EAFFFE#0DF201', switchName:'ISO request', reason:'state refresh'}, null];
}

var target;
if (action === 'on') target = 1;
else if (action === 'off') target = 0;
else if (action === 'toggle') target = (st.state === 1) ? 0 : 1;
else return null;

// Echo guard. The victron-virtual-switch node does not preserve message
// properties, so every state we push into a switch comes straight back out its
// command side stripped of _czoneSync, looking exactly like a user click. We
// therefore remember each value we pushed, per switch and per value, and drop a
// command that merely mirrors one of them.
//
// Per-VALUE timestamps matter: a momentary circuit can be synced 1 then 0 within
// a few hundred ms, and both echoes arrive afterwards. Keeping only the most
// recent sync would fail to match the older echo — which is precisely the loop
// that made the horn oscillate under v7.0.
var e = (flow.get('czEcho') || {})[sw];
if (e && e[target] && now - e[target] < 2500) {
    node.status({fill:'grey', shape:'ring', text:names[sw] + ' echo dropped'});
    return null;
}

// Where the circuit is HEADING, which is not always where CZone last reported
// it: a command already in flight supersedes the reported state. cansend can
// take several hundred ms on a loaded Cerbo, while a momentary switch in VRM
// sends its auto-release only ~400ms after the press — comparing that release
// against the reported state would see "already OFF", drop it, and leave a
// momentary circuit energised once the ON finally landed.
var pending = flow.get('czPending') || {};
var p = pending[sw];
var heading = p ? p.target : st.state;

if (heading === target) {
    node.status({fill:'yellow', shape:'ring',
        text: names[sw] + (p ? ' already pending ' : ' already ') + (target ? 'ON' : 'OFF')});
    return null;
}

// Supersede any command in flight — the newest instruction from the user wins.
pending[sw] = {target: target, cmdTs: now, lastSend: now, sends: 1};
flow.set('czPending', pending);

node.status({fill:'blue', shape:'dot',
    text: names[sw] + ' ' + (target ? 'ON' : 'OFF') + ' @' + new Date().toLocaleTimeString()});

if (MOMENTARY[sw]) {
    // Level control: the output follows the bit. No release frame — that IS the
    // off command, and sending one here would cancel the on we just asked for.
    return [{payload: frame(sw, target), switchNum: sw, switchName: names[sw],
             reason: (target ? 'ON' : 'OFF') + ' (momentary level)'}, null];
}

// Latching: a press toggles, then a release re-arms the press detector. The
// release is ignored by these circuits but the MFD always sends one, and
// bank-10's repeated 01 frames never re-toggled without one, so we mirror it.
return [
    {payload: frame(sw, 1), switchNum: sw, switchName: names[sw], reason: (target ? 'ON' : 'OFF') + ' press'},
    {payload: frame(sw, 0), switchNum: sw, switchName: names[sw], reason: (target ? 'ON' : 'OFF') + ' release'}
];

// Confirm & Retry Engine v7.1 — runs every 250ms.
//
// There is no keep-alive: CZone latches a bank-1 press natively, so nothing has
// to be held and a redeploy no longer drops VRM-lit circuits.
//
// Retrying a latching circuit re-presses, which TOGGLES — a mistimed retry would
// undo a press that actually worked. A retry therefore needs positive evidence of
// failure: a 127501 reading taken *after* our last send that still disagrees.
// The 2.5s floor covers cansend latency, which can reach several hundred ms on
// a loaded Cerbo; only one retry is allowed, because a wrong toggle is far
// worse than making the user click again.

// CZone circuit semantics. How a PGN 127502 bank-1 bit is interpreted is
// decided by the CIRCUIT's own CZone configuration, not by who sent the frame —
// the MFD, the keypads and Node-RED get identical treatment:
//
//   LATCHING (4-11, the lights): 01 is a button press and TOGGLES the latch;
//     00 is the release and is ignored.
//   MOMENTARY (1-3, bilge pumps + horn): the output FOLLOWS the button —
//     01 = on, 00 = off, level control, no toggling.
//
// A latching-style press+release sent to a momentary circuit switches it on and
// then straight back off, so the two must not be conflated.
var MOMENTARY = {1: true, 2: true, 3: true};

var now = Date.now();
var states = flow.get('czState') || {};
var pending = flow.get('czPending') || {};
var names = {1:'Bilge Pump 1',2:'Bilge Pump 2',3:'Horn',4:'Helm Lights',5:'Nav Lights',6:'Anchor Light',7:'Red Light',8:'Flybridge Lights',9:'Underwater Light',10:'Bow Light 1',11:'Bow Light 2'};

function frame(sw, bit) {
    // PGN 127502 bank instance 1, 2 bits per switch: 01 = pressed/on,
    // 00 = released/off, 11 = leave alone. CAN ID 0DF20EFE mirrors the MFD's own
    // frames (0DF20E17, priority 3) with our unclaimed source address.
    var data = [0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF];
    var byteIdx = Math.floor((sw - 1) / 4) + 1;
    var bitPos = ((sw - 1) % 4) * 2;
    data[byteIdx] = (data[byteIdx] & (~(0x03 << bitPos) & 0xFF)) | (bit << bitPos);
    return 'cansend can0 0DF20EFE#' + data.map(function(b) {
        return ('0' + b.toString(16).toUpperCase()).slice(-2); }).join('');
}

var sendsA = [];
var sendsB = [];
var reverts = [];

Object.keys(pending).forEach(function(k) {
    var sw = parseInt(k), p = pending[k];
    var st = states[sw];

    if (st && st.ts >= p.cmdTs && st.state === p.target) {
        delete pending[k];   // CZone applied it — nothing further to do, ever
        return;
    }

    if (now - p.cmdTs > 9000) {
        // Give up: revert the virtual switch to the last real CZone state.
        delete pending[k];
        var rv = st ? st.state : 0;
        reverts.push({sw: sw, state: rv});
        node.warn('CZone: ' + names[sw] + ' ' + (p.target ? 'ON' : 'OFF') +
                  ' unconfirmed after 9s (' + p.sends + ' send' + (p.sends > 1 ? 's' : '') +
                  ') — reverting virtual switch');
        return;
    }

    if (st && st.ts > p.lastSend && st.state !== p.target &&
        now - p.lastSend >= 2500 && p.sends < 2) {
        if (MOMENTARY[sw]) {
            sendsA.push({payload: frame(sw, p.target), switchNum: sw, switchName: names[sw],
                         reason: (p.target ? 'ON' : 'OFF') + ' (momentary retry)'});
        } else {
            sendsA.push({payload: frame(sw, 1), switchNum: sw, switchName: names[sw],
                         reason: (p.target ? 'ON' : 'OFF') + ' press retry'});
            sendsB.push({payload: frame(sw, 0)});
        }
        p.lastSend = now;
        p.sends++;
    }
});

flow.set('czPending', pending);

var nPend = Object.keys(pending).length;
node.status({fill: nPend ? 'blue' : 'grey', shape: 'dot',
    text: nPend ? nPend + ' pending' : 'idle'});

return [sendsA, sendsB, reverts];

// Route {sw, state} revert messages to the right virtual switch input.
// A revert is a write like any other, so record it in the echo map too —
// otherwise it comes straight back as a command and re-triggers the command we
// just gave up on.
var sw = msg.sw;
if (!(sw >= 1 && sw <= 11)) return null;
var echo = flow.get('czEcho') || {};
if (!echo[sw]) echo[sw] = {};
echo[sw][msg.state] = Date.now();
flow.set('czEcho', echo);
var outputs = [null,null,null,null,null,null,null,null,null,null,null];
var m = {payload: {}, _czoneSync: true};
m.payload['/SwitchableOutput/output_1/State'] = msg.state;
outputs[sw - 1] = m;
return outputs;
